style.css:
@-moz-document domain("google.com") {
html, body { height: 100% !important; background: #000 !important; }
  body::before {
    content: "";
    position: fixed; inset: 0;
    background-image: url("https://i.ibb.co/m5y7T95N/29.jpg");
    background-size: cover; background-position: center; background-repeat: no-repeat;
    z-index: -1;
  }

  /* Tidy things up (logo variations) */
  #hplogo, .lnXdpd, img[alt="Google"] { opacity: 0 !important; }
  /* Transparent top bar */
  #gb { background: transparent !important; }
}
